function findCasesForTopic(topic, limit = 2) {
  const kws = topic.replace(/[？?！!。，,.、：:；;「」『』]/g, " ").split(/\s+/).filter((k) => k.length >= 2);
  const scored = DEBATE_CASES.map((c) => {
    let score = 0;
    const hay = `${c.topic}${c.proPoints.join("")}${c.conPoints.join("")}`;
    for (const kw of kws) {
      if (hay.includes(kw)) score += 2;
      if (c.topic.includes(kw)) score += 1;
    }
    return { c, score };
  }).filter((x) => x.score > 0).sort((a, b) => b.score - a.score).map((x) => x.c);
  return scored.slice(0, limit);
}
function randomCase() {
  return DEBATE_CASES[Math.floor(Math.random() * DEBATE_CASES.length)];
}

