function findHotTopicsForTopic(topic, limit = 2) {
  const kws = topic.replace(/[？?！!。，,.、：:；;「」『』]/g, " ").split(/\s+/).filter((k) => k.length >= 2);
  const scored = HOT_TOPICS.map((h) => {
    let score = 0;
    const hay = `${h.title}${h.summary}${h.proPoints.map((p) => p.text).join("")}${h.conPoints.map((p) => p.text).join("")}`;
    for (const kw of kws) {
      if (hay.includes(kw)) score += 2;
      if (h.title.includes(kw)) score += 1;
    }
    return { h, score };
  }).filter((x) => x.score > 0).sort((a, b) => b.score - a.score).map((x) => x.h);
  return scored.slice(0, limit);
}
function buildHotTopicSection(topic) {
  const hits = findHotTopicsForTopic(topic);
  if (hits.length === 0) return "";
  const body = hits.map((h) => {
    const heatStr = "\u{1F525}".repeat(h.heat);
    const pro = h.proPoints.map((p) => `  \xB7 \u6B63\u65B9\uFF1A${p.text}\uFF08${p.source}\uFF09`).join("\n");
    const con = h.conPoints.map((p) => `  \xB7 \u53CD\u65B9\uFF1A${p.text}\uFF08${p.source}\uFF09`).join("\n");
    return `${heatStr} \u3010${h.title}\u3011${h.summary}
${pro}
${con}`;
  }).join("\n\n");
  return `## \u5168\u7F51\u70ED\u95E8\u89C2\u70B9\uFF082026 \u771F\u5B9E\u9AD8\u70ED\u5EA6\u8BDD\u9898\uFF0C\u53EF\u5F15\u7528\u987B\u5E26\u51FA\u5904\uFF09
\u4EE5\u4E0B\u662F\u4E0E\u8FA9\u9898\u76F8\u5173\u7684\u9AD8\u70ED\u5EA6\u793E\u4F1A\u8BA8\u8BBA\u3002\u5F15\u7528\u65F6\u6807\u6CE8\u300C\u636E 2026 \u5E74\u516C\u5F00\u8BA8\u8BBA\u300D\uFF0C\u4E14\u53EA\u53D6\u4E0E\u4F60\u7684\u7ACB\u573A\u76F8\u7B26\u7684\u90E8\u5206\uFF1B\u5BF9\u65B9\u5F15\u7528\u65F6\u53EF\u7528\u53CD\u65B9\u89C2\u70B9\u53CD\u51FB\u3002
${body}`;
}

