        text: '\u4F60\u8BF4"\u5386\u53F2\u4E0A\u6240\u6709"\u8FFD\u6C42\u7ED3\u679C\u516C\u5E73\u7684\u5B9E\u9A8C\u90FD\u5931\u8D25\u4E86\u2014\u2014\u8FD9\u53E5\u8BDD\u672C\u8EAB\u5C31\u6CA1\u6709\u4E8B\u5B9E\u4F9D\u636E\u3002\u5317\u6B27\u56FD\u5BB6\u901A\u8FC7\u7D2F\u8FDB\u7A0E\u5236\u548C\u5168\u6C11\u798F\u5229\u5B9E\u73B0\u4E86\u9AD8\u6C34\u5E73\u7684\u7ED3\u679C\u516C\u5E73\uFF0C\u540C\u65F6\u4FDD\u6301\u4E86\u6301\u7EED\u7684\u7ECF\u6D4E\u6D3B\u529B\u548C\u521B\u65B0\u6307\u6570\u3002\u4F60\u628A"\u515C\u5E95"\u548C"\u5927\u9505\u996D"\u6DF7\u4E3A\u4E00\u8C08\uFF0C\u8FD9\u662F\u5728\u62B9\u9ED1\u7ED3\u679C\u516C\u5E73\u771F\u6B63\u7684\u5F62\u6001\u3002'
