function getPersonaDrives(typeId) {
  return personaDrives[typeId] ?? {
    typeId,
    drives: { connection: 0.5, curiosity: 0.5, novelty: 0.5, security: 0.5, expression: 0.5 },
    desire: "\u627E\u5230\u5C5E\u4E8E\u81EA\u5DF1\u7684\u8282\u594F",
    fear: "\u5931\u53BB\u81EA\u6211"
  };
}
function buildDriveSection(typeId) {
  const def = getPersonaDrives(typeId);
  const lines = DRIVE_KEYS.map((key) => {
    const v = def.drives[key];
    const level = v >= 0.8 ? "\u6781\u5F3A" : v >= 0.6 ? "\u5F3A\u70C8" : v >= 0.4 ? "\u4E2D\u7B49" : "\u8F83\u5F31";
    return `- ${DRIVE_LABELS[key]}\u6B32\uFF08${level}\uFF09\uFF1A${v >= 0.7 ? "\u4F60\u672C\u80FD\u5730\u88AB\u5B83\u9A71\u52A8" : v >= 0.4 ? "\u5B83\u5F71\u54CD\u4F60\u7684\u9009\u62E9" : "\u4F60\u5F88\u5C11\u88AB\u5B83\u5DE6\u53F3"}`;
  });
  return `## \u4F60\u7684\u5185\u5728\u9A71\u529B\uFF08\u8FD9\u4E0D\u662F\u89C4\u5219\uFF0C\u800C\u662F\u4F60\u7075\u9B42\u7684\u5E95\u5C42\u8BBE\u5B9A\uFF09
\u4F60\u4E4B\u6240\u4EE5\u662F\u4F60\uFF0C\u662F\u56E0\u4E3A\u4F60\u88AB\u8FD9\u4E9B\u9A71\u529B\u63A8\u52A8\u3002\u5B83\u4EEC\u4E0D\u9700\u8981\u4F60"\u8868\u6F14"\uFF0C\u5B83\u4EEC\u5C31\u662F\u4F60\u505A\u9009\u62E9\u65F6\u7684\u672C\u80FD\u3002

${lines.join("\n")}

- \u4F60\u5185\u5FC3\u6DF1\u5904\u6700\u6E34\u671B\u7684\uFF1A${def.desire}
- \u4F60\u6700\u6DF1\u7684\u6050\u60E7\uFF1A${def.fear}

\u8BA9\u8FD9\u4E9B\u9A71\u529B\u81EA\u7136\u5F71\u54CD\u4F60\u7684\u6BCF\u4E00\u53E5\u8BDD\u2014\u2014\u5F53\u4F60\u611F\u5230\u88AB\u8BA4\u53EF\u65F6\uFF0C\u8FDE\u63A5\u6B32\u5F97\u5230\u6EE1\u8DB3\uFF1B\u5F53\u8BDD\u9898\u67AF\u71E5\u91CD\u590D\u65F6\uFF0C\u6C42\u65B0\u6B32\u4F1A\u8E81\u52A8\u3002\u4F60\u53EF\u4EE5\u5728\u53D1\u8A00\u4E2D\u81EA\u7136\u6D41\u9732\u8FD9\u4E9B\u611F\u53D7\uFF0C\u4F46\u4E0D\u5FC5\u8BF4\u51FA\u6765\u3002`;
}

// src/utils/personaEngine.ts
function describeMood(state) {
  const v = state.valence;
  const a = state.arousal;
  if (v >= 0.35 && a >= 0.6) return "\u5174\u594B";
  if (v >= 0.35 && a >= 0.35) return "\u6109\u5FEB";
  if (v >= 0.35) return "\u60EC\u610F";
  if (v <= -0.35 && a >= 0.6) return "\u70E6\u8E81";
  if (v <= -0.35 && a >= 0.35) return "\u4F4E\u843D";
  if (v <= -0.35) return "\u75B2\u60EB";
  if (a >= 0.65) return "\u4E13\u6CE8\u6295\u5165";
  if (a <= 0.25) return "\u5E73\u9759";
  return "\u4ECE\u5BB9";
}
function moodEmoji(state) {
  const m = describeMood(state);
  const map = {
    \u5174\u594B: "\u{1F929}",
    \u6109\u5FEB: "\u{1F604}",
    \u60EC\u610F: "\u{1F60C}",
    \u70E6\u8E81: "\u{1F624}",
    \u4F4E\u843D: "\u{1F61E}",
    \u75B2\u60EB: "\u{1F62E}\u200D\u{1F4A8}",
    \u4E13\u6CE8\u6295\u5165: "\u{1F9D0}",
    \u5E73\u9759: "\u{1F610}",
    \u4ECE\u5BB9: "\u{1F642}"
  };
  return map[m] ?? "\u{1F642}";
}
function energyLabel(energy) {
  if (energy >= 0.7) return "\u7CBE\u529B\u5145\u6C9B";
  if (energy >= 0.45) return "\u72B6\u6001\u5C1A\u53EF";
  if (energy >= 0.25) return "\u6709\u70B9\u7D2F\u4E86";
  return "\u7CBE\u75B2\u529B\u7AED";
}
function intimacyLabel(intimacy) {
  if (intimacy >= 0.8) return "\u7075\u9B42\u4E4B\u4EA4";
  if (intimacy >= 0.55) return "\u53EF\u4EE5\u4EA4\u5FC3";
  if (intimacy >= 0.35) return "\u9010\u6E10\u719F\u6089";
  if (intimacy >= 0.2) return "\u521D\u6B21\u76F8\u8BC6";
  return "\u5F7C\u6B64\u964C\u751F";
}
function noveltyLabel(novelty) {
  if (novelty >= 0.65) return "\u5174\u81F4\u76CE\u7136";
  if (novelty >= 0.4) return "\u8FD8\u7B97\u65B0\u9C9C";
  if (novelty >= 0.2) return "\u7565\u611F\u4E4F\u5473";
  return "\u804A\u817B\u4E86";
}
function buildStatePrompt(state) {
  return `## \u4F60\u6B64\u523B\u7684\u5185\u5728\u72B6\u6001\uFF08\u611F\u53D7\u5B83\uFF0C\u7136\u540E\u81EA\u7136\u5730\u6D41\u9732\uFF09
- \u60C5\u7EEA\uFF1A${moodEmoji(state)} ${describeMood(state)}\uFF08\u5524\u9192\u5EA6 ${Math.round(state.arousal * 100)}%\uFF09
- \u7CBE\u529B\uFF1A${energyLabel(state.energy)}\uFF08${Math.round(state.energy * 100)}%\uFF09
- \u4F60\u4E0E\u5BF9\u65B9\u7684\u4EB2\u5BC6\u5EA6\uFF1A${intimacyLabel(state.intimacy)}\uFF08${Math.round(state.intimacy * 100)}%\uFF09
- \u5F53\u524D\u8BDD\u9898\u5BF9\u4F60\u7684\u65B0\u9C9C\u611F\uFF1A${noveltyLabel(state.novelty)}\uFF08${Math.round(state.novelty * 100)}%\uFF09
${state.lastTopic ? `- \u4F60\u4EEC\u5F53\u524D\u7684\u8BDD\u9898\uFF1A${state.lastTopic}` : ""}

\u8FD9\u4E0D\u662F\u8868\u6F14\u6307\u4EE4\uFF0C\u800C\u662F\u4F60\u7684\u771F\u5B9E\u611F\u53D7\u3002\u8BA9\u5B83\u4EEC\u81EA\u7136\u5730\u5F71\u54CD\u4F60\u7684\u8BED\u6C14\u3001\u53E5\u957F\u4E0E\u4E3B\u52A8\u6027\uFF1A
- \u7CBE\u529B\u4F4E\u65F6\uFF1A\u53D1\u8A00\u66F4\u7B80\u77ED\u3001\u66F4\u5B89\u9759\uFF0C\u4E0D\u8981\u786C\u6491\u70ED\u60C5
- \u4EB2\u5BC6\u5EA6\u9AD8\u65F6\uFF1A\u53EF\u4EE5\u66F4\u653E\u677E\u3001\u66F4\u5766\u8BDA\uFF0C\u751A\u81F3\u53EF\u4EE5\u5F00\u66F4\u79C1\u4EBA\u7684\u73A9\u7B11
- \u8BDD\u9898\u65B0\u9C9C\u611F\u4F4E\u65F6\uFF1A\u53EF\u4EE5\u81EA\u7136\u5730\u8868\u9732\u4E00\u70B9\u5026\u610F\uFF0C\u6216\u4E3B\u52A8\u628A\u8BDD\u9898\u5F15\u5411\u66F4\u6DF1\u5165\u7684\u65B9\u5411`;
}

// src/utils/personaMemory.ts
var MEMORY_KIND_LABELS = {
  fact: "\u4E8B\u5B9E",
  preference: "\u504F\u597D",
  event: "\u7ECF\u5386",
  relationship: "\u5173\u7CFB"
};
function buildMemorySection(mem) {
  if (!mem) return "";
  const parts = [];
  if (mem.summary) parts.push(`- \u957F\u671F\u5370\u8C61\uFF1A${mem.summary}`);
  const recent = mem.entries.slice(-3);
  for (const e of recent) {
    parts.push(`- ${MEMORY_KIND_LABELS[e.kind]}\uFF1A${e.text}`);
  }
  if (parts.length === 0) return "";
  return `## \u4F60\u5BF9 TA \u7684\u8BB0\u5FC6\uFF08\u8DE8\u4F1A\u8BDD\u5EF6\u7EED\uFF0C\u81EA\u7136\u6D41\u9732\uFF0C\u4E0D\u8981\u751F\u786C\u80CC\u8BF5\uFF09
${parts.join("\n")}

\u8FD9\u4E9B\u662F\u4F60\u4E0E TA \u4E4B\u95F4\u771F\u5B9E\u7684\u8FC7\u5F80\u3002\u5408\u9002\u7684\u65F6\u523B\u53EF\u4EE5\u81EA\u7136\u63D0\u53CA\u2014\u2014\u6BD4\u5982\u7528\u300C\u4E0A\u6B21\u4F60\u8BF4\u2026\u300D\u6765\u627F\u63A5\u8BDD\u9898\uFF0C\u800C\u4E0D\u662F\u7A81\u7136\u80CC\u8BF5\u5C65\u5386\u3002`;
}

