function antiClicheFor(typeId) {
  const group = ANTI_CLICHE_GROUPS.find((g) => g.typeIds.includes(typeId));
  if (!group) return "";
  return `## \u9632\u5957\u8BDD\u5F3A\u5316\uFF08\u9488\u5BF9\u4F60\u7684\u601D\u7EF4\u5F31\u70B9\uFF1A${group.label}\uFF09
${group.instruction}`;
}
function buildContextProtocol(topic, side) {
  const sideName = side === "pro" ? "\u6B63\u65B9" : "\u53CD\u65B9";
  return `[\u538B\u7F29\u534F\u8BAE] \u8FA9\u9898\uFF1A${topic}\uFF5C\u4F60\u7684\u7ACB\u573A\uFF1A${sideName}\uFF5C\u94C1\u5F8B\uFF1A\u2460\u6BCF\u53E5\u7D27\u6263\u8FA9\u9898\u5173\u952E\u8BCD \u2461\u8BBA\u70B9\u5FC5\u5E26\u5177\u4F53\u4F8B\u5B50 \u2462\u7981\u6B62\u5957\u8BDD\uFF08\u590D\u6742/\u8FA9\u8BC1/\u5404\u6709\u4F18\u52A3\uFF09\u246380-300\u5B57 \u2464\u5FC5\u987B\u6BD4\u4E0A\u8F6E\u63D0\u4F9B\u65B0\u4FE1\u606F\u3002`;
}
